// Minimal Stripe v12 test double for the MigratePR demo.
// Echoes params so tests can assert business-level outcomes.
class Stripe {
  constructor(key, options) {
    this._key = key;
    this._apiVersion = options ? options.apiVersion : undefined;
    this.subscriptions = {
      async del(id) {
        return { id, status: 'canceled' };
      },
      async cancel(id) {
        return { id, status: 'canceled' };
      },
    };
    this.checkout = {
      sessions: {
        async create(params) {
          const id = 'cs_test_' + Math.random().toString(36).slice(2, 10);
          return { id, ...params };
        },
      },
    };
  }
}

module.exports = Stripe;
